+main() {
+    try {
+        std::mt19937 gen(1234);
+        std::uniform_real_distribution<float> dis(-1.0f, 1.0f);
+        int64_t const batch_size = 4, seq_length = 128, hidden_size = 128;
+        int64_t const x_count      = batch_size * seq_length * hidden_size;
+        int64_t const weight_count = batch_size * hidden_size;
+        int64_t const stat_count   = batch_size * seq_length;
+        nv_bfloat16* X_dev         = managed<nv_bfloat16>(x_count);
+        nv_bfloat16* DY_dev        = managed<nv_bfloat16>(x_count);
+        nv_bfloat16* DX_dev        = managed<nv_bfloat16>(x_count);
+        float* Scale_dev           = managed<float>(weight_count);
+        float* Mean_dev            = managed<float>(stat_count);
+        float* InvVar_dev          = managed<float>(stat_count);
+        float* DScale_dev          = managed<float>(weight_count);
+        float* DBias_dev           = managed<float>(weight_count);
+        for (int64_t i = 0; i < (x_count); ++i) X_dev[i] = __float2bfloat16(dis(gen));
+        for (int64_t i = 0; i < (x_count); ++i) DY_dev[i] = __float2bfloat16(dis(gen));
+        for (int64_t i = 0; i < (x_count); ++i) DX_dev[i] = __float2bfloat16(dis(gen));
+        for (int64_t i = 0; i < (weight_count); ++i) Scale_dev[i] = dis(gen);
+        for (int64_t i = 0; i < (stat_count); ++i) Mean_dev[i] = dis(gen);
+        for (int64_t i = 0; i < (stat_count); ++i) InvVar_dev[i] = dis(gen);
+        for (int64_t i = 0; i < (weight_count); ++i) DScale_dev[i] = dis(gen);
+        for (int64_t i = 0; i < (weight_count); ++i) DBias_dev[i] = dis(gen);
+        for (int64_t i = 0; i < stat_count; ++i) InvVar_dev[i] = std::fabs(InvVar_dev[i]) + 0.5f;
+
+        fe::graph::Graph graph{};
+        graph.set_io_data_type(fe::DataType_t::BFLOAT16)
+            .set_intermediate_data_type(fe::DataType_t::FLOAT)
+            .set_compute_data_type(fe::DataType_t::FLOAT);
+        auto X      = graph.tensor(fe::graph::Tensor_attributes()
+                                  .set_name("X")
+                                  .set_dim({batch_size, seq_length, hidden_size})
+                                  .set_stride({seq_length * hidden_size, hidden_size, 1}));
+        auto DY     = graph.tensor(fe::graph::Tensor_attributes()
+                                   .set_name("DY")
+                                   .set_dim({batch_size, seq_length, hidden_size})
+                                   .set_stride({seq_length * hidden_size, hidden_size, 1}));
+        auto Scale  = graph.tensor(fe::graph::Tensor_attributes()
+                                      .set_name("scale")
+                                      .set_dim({batch_size, 1, hidden_size})
+                                      .set_stride({hidden_size, hidden_size, 1})
+                                      .set_data_type(fe::DataType_t::FLOAT));
+        auto Mean   = graph.tensor(fe::graph::Tensor_attributes()
+                                     .set_name("mean")
+                                     .set_dim({batch_size, seq_length, 1})
+                                     .set_stride({seq_length, 1, 1})
+                                     .set_data_type(fe::DataType_t::FLOAT));
+        auto InvVar = graph.tensor(fe::graph::Tensor_attributes()
+                                       .set_name("inv_variance")
+                                       .set_dim({batch_size, seq_length, 1})
+                                       .set_stride({seq_length, 1, 1})
+                                       .set_data_type(fe::DataType_t::FLOAT));
+        auto attrs  = fe::graph::AdaLayernorm_backward_attributes()
+                         .set_name("adalayernorm_backward")
+                         .set_saved_mean_and_inv_variance(Mean, InvVar)
+                         .set_compute_data_type(fe::DataType_t::FLOAT);
+        auto [DX, DScale, DBias] = graph.adalayernorm_backward(DY, X, Scale, attrs);
+        DX->set_output(true).set_data_type(fe::DataType_t::BFLOAT16);
+        DScale->set_output(true).set_data_type(fe::DataType_t::FLOAT);
+        DBias->set_output(true).set_data_type(fe::DataType_t::FLOAT);
+        VariantPack variant_pack = {{X, X_dev},
+                                    {DY, DY_dev},
+                                    {Scale, Scale_dev},
+                                    {Mean, Mean_dev},
+                                    {InvVar, InvVar_dev},
+                                    {DX, DX_dev},
+                                    {DScale, DScale_dev},
+                                    {DBias, DBias_dev}};
+        build_and_execute(graph, variant_pack);
+        std::cout << "adalayernorm_backward executed successfully\n";
+        cudaFree(X_dev);
+        cudaFree(DY_dev);
+        cudaFree(DX_dev);
+        cudaFree(Scale_dev);
+        cudaFree(Mean_dev);
+        cudaFree(InvVar_dev);
+        cudaFree(DScale_dev);
+        cudaFree(DBias_dev);
+    } catch (std::exception const& e) {
+        std::cout << "SKIP: sample did not run on this installation: " << e.what() << "\n";
+        return 0;
+    }
+    return 0;
+}

