+        cudaFree(A_dev);
+        cudaFree(B_dev);
+        cudaFree(C_dev);
+    } catch (std::exception const& e) {
+        std::cout << "SKIP: sample did not run on this installation: " << e.what() << "\n";
+        return 0;
+    }
+    return 0;
+}

