+                                  .set_stride({Hkv * S * D, D, Hkv * D, 1})
+                                  .set_data_type(fe::DataType_t::BFLOAT16));
+        auto V     = graph.tensor(fe::graph::Tensor_attributes()
+                                  .set_name("V")
+                                  .set_dim({B, Hkv, S, D})
