+template <typename T>
+T*
+managed(int64_t count) {
+    T* ptr             = nullptr;
+    cudaError_t status = cudaMallocManaged(&ptr, count * sizeof(T));
+    if (status != cudaSuccess) {
+        throw std::runtime_error(std::string("cudaMallocManaged: ") + cudaGetErrorString(status));
+    }
+    return ptr;
+}
